import{_ as a,c as p,a as n,o as c}from"./app-C-NtBN7U.js";const l={};function r(t,e){return c(),p("div",null,e[0]||(e[0]=[n('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-11-05-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-11-05-资讯日报"><span>2026-11-05 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="openai误封逆向研究账号-11天后致歉解封" tabindex="-1"><a class="header-anchor" href="#openai误封逆向研究账号-11天后致歉解封"><span>OpenAI误封逆向研究账号，11天后致歉解封</span></a></h3><p>安全研究员因用 ChatGPT 辅助逆向自家电视被封号并扣除 500 美元，OpenAI 在 11 天后发邮件致歉并恢复账号，官方表示模型从未禁止逆向工程。</p><p>官方表态：核心研究员称拦截多属意外且正在修复判定边界</p><p>竞品收紧：Anthropic限制Claude逆向并禁止克隆游戏<a href="https://mp.weixin.qq.com/s?__biz=MzU1NTUxNTM0Mg==&amp;chksm=fa0fcd448eaf2c60d878e46cce060c1ea07ab066e0c0a433d071df5173c3a1344508a58c73fb&amp;idx=2&amp;mid=2247589378&amp;sn=812fb78b4590c5792d64b82aad273bb2" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="openai与claude将蒸馏成本抬高5至10倍" tabindex="-1"><a class="header-anchor" href="#openai与claude将蒸馏成本抬高5至10倍"><span>OpenAI与Claude将蒸馏成本抬高5至10倍</span></a></h3><p>OpenAI 与 Claude 采取反蒸馏措施，通过隐藏思维链和限制连续追问，迫使获取数据的提问轮次大幅增加，将蒸馏方的 API 调用成本抬高 5 到 10 倍。</p><p>OpenAI：不再展示思维链，还原思考需提问10到30次</p><p>Anthropic：限制连续追问，需穿插十几个混淆问题掩护<a href="https://mp.weixin.qq.com/s?__biz=Mzk0NDUyODMwNw==&amp;chksm=c2b0b982e03366f927ca493b8b7ca7f2125ef6ab90612110d7ffb9f60a03e796b74a9c0d1e87&amp;idx=1&amp;mid=2247488147&amp;sn=6ae822fab8440727c6df71d829e15cf1" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="claude-code产品负责人cat-wu离职" tabindex="-1"><a class="header-anchor" href="#claude-code产品负责人cat-wu离职"><span>Claude Code产品负责人Cat Wu离职</span></a></h3><p>Anthropic旗下Claude Code产品总负责人Cat Wu宣布离职，这是该团队10天内离开的第4位核心成员。</p><p>此前命令行核心、桌面端主创及工程经理已接连离职</p><p>将Claude Code带成年化数十亿美元的核心业务</p><p>奉行3个月报废原则，模型升级即删20%补丁提示词<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0078dd514b88f7cf496c4650a00f222b3f0a51fb4dcdcf4d883bf4befaf4032aa612eccd5e3&amp;idx=2&amp;mid=2652740261&amp;sn=ad848ca27112af01508620b4099ac007" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="产品应用" tabindex="-1"><a class="header-anchor" href="#产品应用"><span>产品应用</span></a></h2><h3 id="天数智芯端侧设备实测超英伟达thor" tabindex="-1"><a class="header-anchor" href="#天数智芯端侧设备实测超英伟达thor"><span>天数智芯端侧设备实测超英伟达Thor</span></a></h3><p>国产 GPU 厂商天数智芯展示端侧设备彤央 TY1200，标称算力 300 TOPS，可在本地完成机器人仿真训练全流程，实测大模型吞吐超越英伟达 Thor T5000。</p><p>实测表现：首字延迟0.22秒且生成吞吐领先Thor方案</p><p>技术突破：国内首次在端侧本地运行GPU物理仿真引擎</p><p>产品迭代：预告下一代TY2000端侧算力达600T<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=85e6da1691084351fdf74788fbe40753cfc8135a0237b94fab7ae3aa50c3d67cdb8cb31825dc&amp;idx=1&amp;mid=2651072104&amp;sn=f11fab2e4f1f7e5c4204f3524123f1ee" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="百度发布世界模型-无人车日测十万公里" tabindex="-1"><a class="header-anchor" href="#百度发布世界模型-无人车日测十万公里"><span>百度发布世界模型，无人车日测十万公里</span></a></h3><p>百度 Apollo 发布世界模型 Apollo World，能同步生成街景画面与激光雷达点云并实时博弈。无人车在云端日测里程达十万公里，相当于真车连续测试约 3 年。</p><p>仿真交互：支持十分钟以上连续推演，响应延迟在33毫秒内</p><p>业务落地：已用于训练萝卜快跑端到端大模型并在多城跑单<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f05533102b374705b58b3832cac52557b9af06de838be1f41d0ccb10c129a925c4e190a43ca9&amp;idx=1&amp;mid=2652740261&amp;sn=3ae30a3d5d9466d8bfdcb5bd4820a9b9" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="revolut改用智谱glm省下90-成本" tabindex="-1"><a class="header-anchor" href="#revolut改用智谱glm省下90-成本"><span>Revolut改用智谱GLM省下90%成本</span></a></h3><p>Revolut 改用 56 张英伟达 B200 自托管智谱 GLM 模型，AI 推理成本直降约 90%，工程师编码时间缩短 60%。</p><p>每百万 Token 约 0.3 美元，仅为商业服务十分之一</p><p>用 NVFP4 低精度量化将首字延迟降至 1.68 秒</p><p>代码交给 GLM，视觉任务仍调 GPT 和 Gemini<a href="https://mp.weixin.qq.com/s?__biz=MzU1NTUxNTM0Mg==&amp;chksm=fa65db0a487163cc0b916fe928a760b5735da0eaccf6206c70707ae7d78ae0c8c1538aad4b57&amp;idx=1&amp;mid=2247589378&amp;sn=1372371c444a842fa195c9d0ca4a6bb4" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="chatgpt-上线-gif-原生生成与逐帧编辑" tabindex="-1"><a class="header-anchor" href="#chatgpt-上线-gif-原生生成与逐帧编辑"><span>ChatGPT 上线 GIF 原生生成与逐帧编辑</span></a></h3><p>OpenAI 推出 Images 2.6 模型，ChatGPT 现已支持直接生成 GIF 并可逐帧编辑，各订阅档位及 API 今日上线，生图速度提升 50%。</p><p>动图编辑：支持调节播放速度、单帧修改与直接导出</p><p>推 Flare 与 Sunburst 两模型，支持导出 SVG<a href="https://mp.weixin.qq.com/s?__biz=MzA5MTIxNTY4MQ==&amp;chksm=86f2842ce66da05944b67aa730bde94d0d87f58f59ba45cac02caf243e116c6c2173acd2f4a3&amp;idx=1&amp;mid=2461161886&amp;sn=e2f2041415ba95c5e3595b2ed478bb46" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="推荐文章" tabindex="-1"><a class="header-anchor" href="#推荐文章"><span>推荐文章</span></a></h2><h3 id="salesforce研究员-ai包揽我九成代码" tabindex="-1"><a class="header-anchor" href="#salesforce研究员-ai包揽我九成代码"><span>Salesforce研究员：AI包揽我九成代码</span></a></h3><p>Salesforce 工程师 Ben Stolovitz 复盘发现，机器已写了他 90% 以上的代码。他每月 token 消耗约 3000 美元，但因产出平庸已停用 AI 写作与做图。</p><p>编程模式：日常同时管理 5 到 6 个智能体并发开发</p><p>人工把关：模型易过度设计产出垃圾，仍需人把控架构</p><p>研究写作：AI 生成文本空洞谄媚且易带偏思路，坚持手写<a href="https://mp.weixin.qq.com/s?__biz=MzE5OTIyODc3OA==&amp;chksm=97fbc35eb6ec233785401015d613179e5626f78fde3089941ecfeb3dd5fdc2320660fe645e19&amp;idx=3&amp;mid=2247525309&amp;sn=c721a3f6fe815085e314a3cc5b3e3e1d" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="蚂蚁开源机器人底座-获李飞飞团队采用" tabindex="-1"><a class="header-anchor" href="#蚂蚁开源机器人底座-获李飞飞团队采用"><span>蚂蚁开源机器人底座，获李飞飞团队采用</span></a></h3><p>蚂蚁旗下灵波开源的机器人“大脑全栈 2.0”已在零售药房落地分拣，不仅被李飞飞团队接入研究框架，开源模型下载量已突破220万次。</p><p>机构采用：李飞飞团队及KAIST均引入其模型做研究</p><p>模型蒸馏：助4.5亿参数小模型任务成功率升至51.2%</p><p>生态集成：已合入LeRobot并适配SGLang等推理框架<a href="https://mp.weixin.qq.com/s?__biz=MzU1NDA4NjU2MA==&amp;chksm=fa235044a4cae82538c09e582b77e068dc1ac9280007b48d2d1551f481c7b63e7b92a5adc351&amp;idx=1&amp;mid=2247669144&amp;sn=2d43de358366fbe915411a2ccfbd55a5" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="腾讯混元hy4支持操作电脑并计划开源" tabindex="-1"><a class="header-anchor" href="#腾讯混元hy4支持操作电脑并计划开源"><span>腾讯混元Hy4支持操作电脑并计划开源</span></a></h3><p>腾讯发布混元Hy4正式版，首次加入视觉理解与电脑操作能力并计划开源权重；官方坦承多数跑分仍落后于顶尖闭源模型，但在内部科研评测中位居开源第一。</p><p>耗时4小时调用工具1492次，能在已有工程上改需求</p><p>助北大团队找到MPV数学猜想反例并完成形式化验证</p><p>复杂任务中偶发底层数据不同步和镜头不连贯等缺陷<a href="https://mp.weixin.qq.com/s?__biz=MzU5OTI0NTc3Mg==&amp;chksm=fff47f9bffccd2b1639e15c2a136f410173b5c37d832be796296182f97a689d88a7309330f91&amp;idx=1&amp;mid=2247560005&amp;sn=61dbe137aac2e67e067675b6347be25e" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="算法论文" tabindex="-1"><a class="header-anchor" href="#算法论文"><span>算法论文</span></a></h2><h3 id="谷歌联合发布ple-ai工程方案合格率仅41" tabindex="-1"><a class="header-anchor" href="#谷歌联合发布ple-ai工程方案合格率仅41"><span>谷歌联合发布PLE：AI工程方案合格率仅41%</span></a></h3><p>Google 与 Mercor 联合发布物理工程评测 PLE。测试显示 Claude 模型虽能满足 91% 的单项约束，但因各项条件关联，仅 41.3% 的方案满足全部硬性安全要求。</p><p>涵盖机电土木85项任务，硬约束不达标则优化计零分</p><p>参数改动牵连物理约束，多轮修改极易出现版本失效</p><p>同一模型在相同任务运行3次得分平均跨度达15.4%<a href="https://mp.weixin.qq.com/s?__biz=MzA5ODEzMjIyMA==&amp;chksm=91c59be0748932c142b7d3cc3654a524adeec5d13ca192e9f546e9e916d60aae4fe84c0f43cf&amp;idx=1&amp;mid=2247748495&amp;sn=a771b1b52e000acebda514a8df7737bc" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',60)]))}const d=a(l,[["render",r]]),h=JSON.parse('{"path":"/posts/2026-11-05.html","title":"AI日报：OpenAI误封逆向研究账号，11天后致歉解封; OpenAI与Claude将蒸馏成本抬高5至10倍; Claude Code产品负责人Cat Wu离职","lang":"zh-CN","frontmatter":{"date":"2026-11-05T00:00:00.000Z","title":"AI日报：OpenAI误封逆向研究账号，11天后致歉解封; OpenAI与Claude将蒸馏成本抬高5至10倍; Claude Code产品负责人Cat Wu离职"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"OpenAI误封逆向研究账号，11天后致歉解封","slug":"openai误封逆向研究账号-11天后致歉解封","link":"#openai误封逆向研究账号-11天后致歉解封","children":[]},{"level":3,"title":"OpenAI与Claude将蒸馏成本抬高5至10倍","slug":"openai与claude将蒸馏成本抬高5至10倍","link":"#openai与claude将蒸馏成本抬高5至10倍","children":[]},{"level":3,"title":"Claude Code产品负责人Cat Wu离职","slug":"claude-code产品负责人cat-wu离职","link":"#claude-code产品负责人cat-wu离职","children":[]}]},{"level":2,"title":"产品应用","slug":"产品应用","link":"#产品应用","children":[{"level":3,"title":"天数智芯端侧设备实测超英伟达Thor","slug":"天数智芯端侧设备实测超英伟达thor","link":"#天数智芯端侧设备实测超英伟达thor","children":[]},{"level":3,"title":"百度发布世界模型，无人车日测十万公里","slug":"百度发布世界模型-无人车日测十万公里","link":"#百度发布世界模型-无人车日测十万公里","children":[]},{"level":3,"title":"Revolut改用智谱GLM省下90%成本","slug":"revolut改用智谱glm省下90-成本","link":"#revolut改用智谱glm省下90-成本","children":[]},{"level":3,"title":"ChatGPT 上线 GIF 原生生成与逐帧编辑","slug":"chatgpt-上线-gif-原生生成与逐帧编辑","link":"#chatgpt-上线-gif-原生生成与逐帧编辑","children":[]}]},{"level":2,"title":"推荐文章","slug":"推荐文章","link":"#推荐文章","children":[{"level":3,"title":"Salesforce研究员：AI包揽我九成代码","slug":"salesforce研究员-ai包揽我九成代码","link":"#salesforce研究员-ai包揽我九成代码","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"蚂蚁开源机器人底座，获李飞飞团队采用","slug":"蚂蚁开源机器人底座-获李飞飞团队采用","link":"#蚂蚁开源机器人底座-获李飞飞团队采用","children":[]},{"level":3,"title":"腾讯混元Hy4支持操作电脑并计划开源","slug":"腾讯混元hy4支持操作电脑并计划开源","link":"#腾讯混元hy4支持操作电脑并计划开源","children":[]}]},{"level":2,"title":"算法论文","slug":"算法论文","link":"#算法论文","children":[{"level":3,"title":"谷歌联合发布PLE：AI工程方案合格率仅41%","slug":"谷歌联合发布ple-ai工程方案合格率仅41","link":"#谷歌联合发布ple-ai工程方案合格率仅41","children":[]}]}],"git":{"updatedTime":1793965607000,"contributors":[{"name":"GitHub Actions","username":"","email":"actions@github.com","commits":1}],"changelog":[{"hash":"68c9fd4ab2b6b40b96b9f80c1ffdd5e0a8b8a8f0","time":1793965607000,"email":"actions@github.com","author":"GitHub Actions","message":"Auto-commit generated files on 2026-11-06T11:46:47.137Z"}]},"filePathRelative":"posts/2026-11-05.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-11-05 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>OpenAI误封逆向研究账号，11天后致歉解封</h3>\\n<p>安全研究员因用 ChatGPT 辅助逆向自家电视被封号并扣除 500 美元，OpenAI 在 11 天后发邮件致歉并恢复账号，官方表示模型从未禁止逆向工程。</p>"}');export{d as comp,h as data};
